def compute(vars):
    total_gain = vars["v1"]
    third_quarter_gain = vars["v2"]
    not_recorded_in_third_quarter = total_gain - third_quarter_gain

    return {
        "value": not_recorded_in_third_quarter,
        "trace": {
            "total_gain": total_gain,
            "third_quarter_gain": third_quarter_gain,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
